<?php
declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');
try{$c=require __DIR__.'/config.php';$pdo=new PDO("mysql:host={$c['host']};dbname={$c['database']};charset=utf8mb4",$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$a=$_GET['action']??'';
if($_SERVER['REQUEST_METHOD']==='GET'){$tracks=$pdo->query('SELECT id,title FROM goal_tracks ORDER BY created_at')->fetchAll(PDO::FETCH_ASSOC);$tasks=$pdo->query('SELECT id,track_id,goal_month,title,status FROM goal_tasks ORDER BY goal_month,created_at')->fetchAll(PDO::FETCH_ASSOC);echo json_encode(compact('tracks','tasks'));exit;}
$d=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);if($a==='track')$pdo->prepare('INSERT INTO goal_tracks(id,title) VALUES(?,?)')->execute([$d['id'],trim($d['title'])]);elseif($a==='task')$pdo->prepare('INSERT INTO goal_tasks(id,track_id,goal_month,title) VALUES(?,?,?,?)')->execute([$d['id'],$d['track_id'],$d['goal_month'],trim($d['title'])]);elseif($a==='toggle')$pdo->prepare("UPDATE goal_tasks SET status=IF(status='planned','realised','planned') WHERE id=?")->execute([$d['id']]);elseif($a==='track_update'){$title=trim((string)($d['title']??''));if($title==='')throw new RuntimeException('Le titre est obligatoire.');$pdo->prepare('UPDATE goal_tracks SET title=? WHERE id=?')->execute([$title,$d['id']]);}else throw new RuntimeException('Action inconnue.');echo json_encode(['ok'=>true]);}catch(Throwable $e){http_response_code(422);echo json_encode(['error'=>$e->getMessage()]);}
